customMethods.script:
if not self.view.custom.editMode: return

system.perspective.print('deleteCheckItemHistory() called')
for item in self.view.custom.tables.chkItems.selection.data:
	retVal = system.kanoa.quality.config.deleteCheckWithHistory(item['chkItemId'], self.view.custom.info.userId)
	if retVal > 0: 
		system.perspective.sendMessage('showSuccessfulToast', {'message': '%s deleted'%item['chkItemName']})
		if self.view.custom.info.chkShtInfo.chkShtVersionStateName != 'Draft':
			change = "Check Item %s deleted"%(item['chkItemName'])
			system.kanoa.quality.sheet.addChangeLog({'chkShtId': item['chkShtId'], 'change': change}, self.view.custom.security.userId)
			self.view.refreshBinding("custom.changeLog")
	else: system.perspective.sendMessage('showFailerToast', {'message': 'Failed to delete %s'%item['chkItemName']})

self.view.refreshBinding("custom.tables.chkItems.data")

return

chkShtInfo = dict(self.view.custom.info.chkShtInfo)
system.perspective.print("saveChkShtInfo() called for %s"%chkShtInfo)

if not self.view.custom.editMode: 
	system.perspective.print("Not in edit mode")
	return

if (chkShtInfo['chkShtName'] or None) is None:
	system.perspective.print("Invalid name")
	return	#Can't save it if it doesn't have a name

chkShtId = self.view.custom.info.chkShtInfo.chkShtId

getChkShtId = system.kanoa.utilities.getFieldValue('chkShtId', system.kanoa.quality.sheet.getSheets({'chkShtName':chkShtInfo['chkShtName']}))
if getChkShtId and getChkShtId != chkShtId:
	system.perspective.sendMessage('showFailerToast', {'message': 'A Check Sheet with this name already exists'})
	return	

if chkShtId is None:
	chkShtInfo['enabled'] = True
	chkShtId, msg = system.kanoa.quality.sheet.addSheet(chkShtInfo, self.view.custom.security.userId)
	groupId = system.kanoa.quality.config.addGroup({'chkShtId': chkShtId, 'chkItemGroupName':'Main', 'sortOrder':0}, self.view.custom.security.userId)
	if msg is None:
		system.perspective.sendMessage('showSuccessfulToast', {'message': 'Check Sheet created '})			
		comment = 'User created check sheet'
		chkShtVersionStateId = system.kanoa.utilities.getFieldValue('chkShtVersionStateId', system.kanoa.quality.sheet.getSheetVersionStates({'chkShtVersionStateName': 'Draft'}))
		chkShtVersionInfo = {'chkShtId': chkShtId, 'masterChkShtId': chkShtId, 'chkShtVersionStateId': chkShtVersionStateId, 'chkShtVersionNumber': 1, 'comment': comment}
		retVal, msg = system.kanoa.quality.sheet.addSheetVersionHistory(chkShtVersionInfo, self.view.custom.security.userId)
		if msg: system.perspective.sendMessage('showFailerToast', {'message': "Couldn't add version history. %s"%msg})
	else: system.perspective.sendMessage('showFailerToast', {'message': msg})
else:
	chkShtInfo['chkShtId'] = chkShtId
	compareInfo = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.quality.sheet.getSheets({'chkShtId':chkShtId}), 0)
	if all((dict(chkShtInfo).get(k) == v for k, v in dict(compareInfo).items())): 
		system.perspective.sendMessage('showWarningToast', {'message': "No changes found. No need to save"})
		return #Don't save if nothing has changed
	self.logChanges(compareInfo, chkShtInfo)

	retVal, msg = system.kanoa.quality.sheet.updateSheet(chkShtInfo, self.view.custom.security.userId)
	if msg is None: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Check Sheet info updated'})
	else: system.perspective.sendMessage('showFailerToast', {'message': msg})

self.view.params.chkShtId = chkShtId

return

